import math

def find_sequence(m, s):
    # Check if the set S can form a valid sequence
    def is_valid_sequence(seq):
        for i in range(len(seq)):
            for j in range(i, len(seq)):
                current_gcd = seq[i]
                for k in range(i + 1, j + 1):
                    current_gcd = math.gcd(current_gcd, seq[k])
                if current_gcd not in s:
                    return False
        return True

    # Try to find a sequence of length 1
    if m == 1:
        if s[0] == 1:
            return "1\n1"
        else:
            return "-1"

    # Try to find a sequence of length 2
    if m == 2:
        if s[1] % s[0] == 0:
            return "2\n1 2"
        else:
            return "-1"

    # Try to find a sequence of length 3
    if m == 3:
        if s[2] % s[1] == 0 and s[1] % s[0] == 0:
            return "3\n1 2 3"
        else:
            return "-1"

    # Try to find a sequence of length 4
    if m == 4:
        if s[3] % s[2] == 0 and s[2] % s[1] == 0 and s[1] % s[0] == 0:
            return "4\n1 2 3 4"
        else:
            return "-1"

    # General case: try to find a sequence of length up to 4000
    for n in range(1, 4001):
        for start in range(1, 10**6 // n + 1):
            seq = [start + i for i in range(n)]
            if is_valid_sequence(seq):
                return f"{n}\n{' '.join(map(str, seq))}"

    return "-1"

